            {
                failures.AppendLine($"{account} stock={stock} bloquée={jammed?.ToString() ?? "aucune"} dépôt {notes}: attendu {expected}, obtenu {actualTuple}");
            }
        }

        Assert.True(count == 0, $"{count} écart(s) :\n{failures}");
